// Generated by ds-sync (radio template, Web Components) from Figma "RadioField". Do not edit by hand.
// Visuals come from Figma. Behaviour: WAI-ARIA radio group pattern (native radio inputs; the group manages selection, arrow keys and the Tab stop across shadow roots).
import { LitElement, html, nothing, unsafeCSS } from 'lit';

import { icon } from '../../icons/icon';
import '../RadioControl/ds-radio-control';
import css from './RadioField.css?inline';

export class DsRadioField extends LitElement {
  static override styles = [unsafeCSS(':host { display: contents; }'), unsafeCSS(css)];
  static override properties = {
    label: { type: String },
    name: { type: String },
    value: { type: String },
    checked: { type: Boolean },
    state: { type: String, reflect: true, attribute: "state" },
    position: { type: String, reflect: true, attribute: "position" },
    disabled: { type: Boolean, reflect: true },
    forceState: { type: String, attribute: 'data-force-state' },
  };

  /** Figma: the label text ("Radio label") */
  declare label: string | undefined;
  /** Passed to the radio */
  declare name: string | undefined;
  /** Passed to the radio */
  declare value: string;
  /** Initially selected */
  declare checked: boolean;
  /** Figma: State */
  declare state: "enabled" | "invalid" | "warning" | "read-only" | "skeleton";
  /** Figma: Position */
  declare position: "left" | "right";
  /** Figma: State=Disabled */
  declare disabled: boolean;
  /** Renders a pseudo state statically for docs and visual tests: "hover", "pressed" or "focus". */
  declare forceState: string | undefined;

  constructor() {
    super();
    this.label = undefined;
    this.name = undefined;
    this.value = 'on';
    this.checked = false;
    this.state = "enabled";
    this.position = "left";
    this.disabled = false;
  }

  /** Clicking the label text selects the radio (the radio's input sits in another shadow root). */
  private onLabelClick(event: Event) {
    const control = this.renderRoot.querySelector('ds-radio-control') as (HTMLElement & { select(): void }) | null;
    if (!control || event.composedPath().includes(control)) return;
    event.preventDefault();
    control.select();
    control.focus();
  }

  override render() {
    return html`<div class="root" part="root" data-state=${this.state} data-position=${this.position} ?data-disabled=${this.disabled} data-force-state=${this.forceState ?? nothing}>
        <label class="radioRow" @click=${this.onLabelClick}>
          <span class="radioControl"><ds-radio-control accessible-label=${typeof this.label === 'string' ? this.label : "Radio label"} name=${this.name ?? nothing} .value=${this.value} ?checked=${this.checked} ?disabled=${this.disabled} state=${(["enabled","skeleton","read-only","invalid","warning"] as string[]).includes(this.state) ? this.state : 'enabled'}></ds-radio-control></span>
          <span class="value">${this.label ?? "Radio label"}</span>
        </label>
        <div class="statusRow">
          <span class="statusIcon" aria-hidden="true">${icon("statusError16")}</span>
          <span class="errorText">${"Please select an option"}</span>
          <span class="warningText">${"This selection may need review"}</span>
        </div>
      </div>`;
  }
}

if (!customElements.get('ds-radio-field')) customElements.define('ds-radio-field', DsRadioField);

declare global {
  interface HTMLElementTagNameMap {
    'ds-radio-field': DsRadioField;
  }
}
